def main() -> None:
    for lang, fixes in sorted(FIXES.items()):
        path = L10N / f"_quality_fixes_{lang}.json"
        with path.open("w", encoding="utf-8") as f:
            json.dump(fixes, f, ensure_ascii=False, indent=4)
            f.write("\n")
        print(f"Wrote {path.name}: {len(fixes)} fixes")


if __name__ == "__main__":
    main()
